 * - `region_proto` is a proto‑structure that describes which part of the
 *   interior [1, N-1) × [1, N-1) should be updated and in which order
 *   (e.g. plain slices or tiled with into_blocks + hoist).
 * - The actual loop nest is entirely expressed via a Noarr traverser.
 */
template<class SrcBag, class DstBag, class Proto>
inline void jacobi_sweep_region(num_t w, SrcBag src, DstBag dst, Proto region_proto) {
	using namespace noarr;

	traverser(src, dst)
		.order(region_proto)
		.for_each([&](auto state) {
			// state contains logical interior coordinates (i, j)
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			dst[state] = w * (src[state] + src[west] + src[east] + src[south] + src[north]);
		});
}


