	constexpr std::size_t tile_j = 32; // tile width   (cols)

	// Largest multiples of tile_i / tile_j that fit completely into the
	// interior. The remaining "tails" are handled separately using plain
	// sliced traversals, so we still update all interior points exactly once.
	const std::size_t full_i = (inner_len / tile_i) * tile_i;
	const std::size_t full_j = (inner_len / tile_j) * tile_j;

