	//
	// We split the interior [1, N-1) × [1, N-1) into up to four disjoint
	// subregions:
	//
	//   1) Fully tiled block:
	//        i ∈ [1,          1 + full_i)
	//        j ∈ [1,          1 + full_j)
	//      -> processed with 2D tiling (into_blocks on i and j)
	//
	//   2) Right "stripe" (j tail), same rows as 1), remaining columns:
	//        i ∈ [1,          1 + full_i)
	//        j ∈ [1+full_j,   1 + inner_len)
	//
	//   3) Bottom "stripe" (i tail), remaining rows, same columns as 1):
	//        i ∈ [1+full_i,   1 + inner_len)
	//        j ∈ [1,          1 + full_j)
	//
	//   4) Bottom-right corner (both tails):
	//        i ∈ [1+full_i,   1 + inner_len)
	//        j ∈ [1+full_j,   1 + inner_len)
	//
	// This covers the entire interior, regardless of whether inner_len is
	// divisible by tile_i / tile_j. All regions are expressed as Noarr
	// proto-structures and reused for both sweeps.

	// 1) Fully tiled region: [1, 1+full_i) × [1, 1+full_j)
	//    We first slice the interior, then split i and j into tiles using
	//    into_blocks, and finally hoist the tile indices 'I' and 'J' so that
	//    for_each iterates as:
	//        for I (tile rows)
	//          for J (tile cols)
	//            for i (intra-tile rows)
	//              for j (intra-tile cols)
	//
	//    The state seen inside for_each still carries only logical 'i' and 'j'
	//    indices; 'I' and 'J' exist only to drive the traversal order.
	auto tiled_region =
		noarr::slice<'i'>(1, full_i) ^
		noarr::slice<'j'>(1, full_j) ^
		noarr::into_blocks<'i', 'I', 'i'>(noarr::lit<tile_i>) ^
		noarr::into_blocks<'j', 'J', 'j'>(noarr::lit<tile_j>) ^
		noarr::hoist<'I'>() ^
		noarr::hoist<'J'>();

	// 2) Right stripe: [1, 1+full_i) × [1+full_j, 1+inner_len)
	auto right_stripe =
		noarr::slice<'i'>(1, full_i) ^
		noarr::slice<'j'>(1 + full_j, inner_len - full_j);

	// 3) Bottom stripe: [1+full_i, 1+inner_len) × [1, 1+full_j)
	auto bottom_stripe =
		noarr::slice<'i'>(1 + full_i, inner_len - full_i) ^
		noarr::slice<'j'>(1, full_j);

	// 4) Bottom-right corner: [1+full_i, 1+inner_len) × [1+full_j, 1+inner_len)
	auto bottom_right =
		noarr::slice<'i'>(1 + full_i, inner_len - full_i) ^
		noarr::slice<'j'>(1 + full_j, inner_len - full_j);

	const num_t w = (num_t)0.2; // stencil weight, hoisted out of loops

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// ---------------------------------------------------------------------
		// First sweep: B := stencil(A) on the whole interior
		// ---------------------------------------------------------------------
		jacobi_sweep_region(w, A, B, tiled_region);
		jacobi_sweep_region(w, A, B, right_stripe);
		jacobi_sweep_region(w, A, B, bottom_stripe);
		jacobi_sweep_region(w, A, B, bottom_right);

		// ---------------------------------------------------------------------
		// Second sweep: A := stencil(B) on the whole interior
		// ---------------------------------------------------------------------
		jacobi_sweep_region(w, B, A, tiled_region);
		jacobi_sweep_region(w, B, A, right_stripe);
		jacobi_sweep_region(w, B, A, bottom_stripe);
		jacobi_sweep_region(w, B, A, bottom_right);
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set lengths of dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_2d((int)tsteps, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
